// server.js (Node.js/Express backend skeleton)

const express = require('express');
const http = require('http');
const socketIO = require('socket.io');
const mongoose = require('mongoose');
const cors = require('cors');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');

const app = express();
const server = http.createServer(app);
const io = socketIO(server, { cors: { origin: process.env.FRONTEND_URL } });

// Middleware
app.use(cors());
app.use(express.json());

// DB Connection
mongoose.connect(process.env.MONGODB_URI, { useNewUrlParser: true, useUnifiedTopology: true });

// Models (Mongoose schemas)
const userSchema = new mongoose.Schema({
  name: String,
  email: { type: String, unique: true },
  passwordHash: String,
  preferences: [String],
  interactions: [{ contentId: String, type: String, timestamp: Date }]
});
const User = mongoose.model('User', userSchema);

const contentSchema = new mongoose.Schema({
  title: String,
  type: { type: String, enum: ['literature', 'music', 'visual_art', 'film'] },
  region: String,
  tags: [String],
  externalRefId: String
});
const Content = mongoose.model('Content', contentSchema);

// Auth Routes
app.post('/api/auth/register', async (req, res) => {
  const { name, email, password } = req.body;
  const passwordHash = await bcrypt.hash(password, 10);
  const user = new User({ name, email, passwordHash });
  await user.save();
  const token = jwt.sign({ userId: user._id }, process.env.JWT_SECRET);
  res.json({ token, user: { id: user._id, name, email } });
});

app.post('/api/auth/login', async (req, res) => {
  const { email, password } = req.body;
  const user = await User.findOne({ email });
  if (!user || !await bcrypt.compare(password, user.passwordHash)) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }
  const token = jwt.sign({ userId: user._id }, process.env.JWT_SECRET);
  res.json({ token, user: { id: user._id, name, email } });
});

// Content & Recommendation Routes
app.get('/api/content', async (req, res) => {
  const { type, region, limit = 20 } = req.query;
  const query = {};
  if (type) query.type = type;
  if (region) query.region = region;
  const contents = await Content.find(query).limit(parseInt(limit));
  res.json(contents);
});

app.get('/api/recommendations', async (req, res) => {
  const userId = req.user.id; // from JWT
  const user = await User.findById(userId).populate('interactions.contentId');

  // Simple content-based: recommend by user’s preferred regions/tags
  const preferredTags = [...new Set(user.preferences.flatMap(p => p.split(',')))];
  const recommended = await Content.find({ tags: { $in: preferredTags } })
    .limit(10)
    .sort('-_id');

  res.json(recommended);
});

// Chat via Socket.IO
io.on('connection', (socket) => {
  socket.on('joinRoom', (roomId) => {
    socket.join(roomId);
  });

  socket.on('sendMessage', async (data) => {
    const { roomId, senderId, text } = data;
    const message = { roomId, senderId, text, timestamp: new Date(), read: false };
    io.to(roomId).emit('receiveMessage', message);
  });
});

// External API Proxy (e.g., Wikimedia)
app.get('/api/external/facts', async (req, res) => {
  const { region } = req.query;
  const response = await fetch(`https://commons.wikimedia.org/w/api.php?action=query&prop=pageimages&format=json&piprop=original&titles=${region}`);
  const data = await response.json();
  res.json(data);
});

const PORT = process.env.PORT || 5000;
server.listen(PORT, () => console.log(`Server running on port ${PORT}`));
"""


